sparql:
SELECT ?work ?workLabel
WHERE {
  # Wikidata QID for Mexico City
  VALUES ?cityQID { wd:Q1489 }
  {
    # Search for works in the MusicBrainz graph
    GRAPH <https://linkedmusic.ca/graphs/musicbrainz/> {
      ?work rdf:type mb:Work .
      { ?work wdt:P1071 ?locationObject . } # location of creation
      UNION
      { ?work wdt:P4647 ?locationObject . } # location
      # Handle both direct links to an Area and links to a Place within an Area
      {
        # Case 1: The location is the city/area itself
        ?locationObject rdf:type mb:Area .
        BIND(?locationObject AS ?cityArea)
      }
      UNION
      {
        # Case 2: The location is a venue (Place), so we find its containing city (Area)
        ?locationObject rdf:type mb:Place .
        ?locationObject wdt:P131 ?cityArea .
        ?cityArea rdf:type mb:Area .
      }
      # Match the final city/area to Mexico City's QID
      ?cityArea wdt:P2888 ?cityQID .
      OPTIONAL { ?work rdfs:label ?workLabel . }
    }
  }
  UNION
  {
    # Search for compositions in the DIAMM graph
    GRAPH <https://linkedmusic.ca/graphs/diamm/> {
      ?work rdf:type diamm:Composition .

      ?work wdt:P361 ?source .
      ?source rdf:type diamm:Source .
      ?source wdt:P131 ?city .
      ?city rdf:type diamm:City .

      ?city wdt:P2888 ?cityQID .
      OPTIONAL { ?work rdfs:label ?workLabel . }
    }
  }
}
